// The disk functions and their tangents: out = (radius, omega, inner, outer), tout[4 d + j].
template <typename Real, int P>
RM_HD inline void disk_jvp(const Real x[4], const Real* params, const Real* dx, const Real* dparams,
                           Real out[4], Real* tout) {
  (void)x;
  (void)params;
  (void)dx;
  (void)dparams;
  constexpr int NP = 2;
  (void)NP;
  const Real t10 = x[1] * x[1];
  const Real t11 = x[2] * x[2];
  const Real t13 = x[3] * x[3];
  const Real t14 = t10 + t11 + t13;
  const Real t15 = sqrt(t14);
  const Real t23 = Real(1.0) / (t15 * t15);
  const Real t8 = params[0] * params[1];
  const Real t18 = t8 * t8;
  const Real t20 = t18 * Real(-1.0);
  const Real t87 = params[0] * t15;
  const Real t88 = t20 + t87;
  const Real t89 = sqrt(t88);
  const Real t90 = t23 * t89;
  const Real t57 = params[1] * params[1];
  const Real t62 = t57 * Real(-9.0);
  const Real t64 = params[1] * params[1] * params[1] * params[1];
  const Real t65 = Real(2.0) * t64;
  const Real t71 = t57 * Real(-4.0);
  const Real t72 = Real(5.0) + t71;
  const Real t73 = Real(-1.0) * t57;
  const Real t74 = Real(1.0) + t73;
  const Real t75 = t72 * t74;
  const Real t76 = sqrt(t75);
  const Real t77 = t57 * t76;
  const Real t78 = Real(8.0) + t62 + t65 + t77;
  const Real t81 = pow(t78, Real(0.3333333333333333));
  const Real t83 = Real(-1.0) * t57 * t76;
  const Real t84 = Real(8.0) + t62 + t65 + t83;
  const Real t85 = pow(t84, Real(0.3333333333333333));
  const Real t86 = Real(2.0) + t81 + t85;
  const Real t91 = params[0] * t86;
  const Real t93 = params[0] * Real(20.0);
  const Real t25 = Real(1.0) / (t15);
  const Real t96 = Real(1.0) / (t15 * t15 * t15);
  const Real t785 = Real(1.0) / (t89);
  const Real t790 = pow(t78, Real(-0.6666666666666667));
  const Real t794 = params[1] * params[1] * params[1];
  const Real t804 = Real(1.0) / (t76);
  const Real t810 = pow(t84, Real(-0.6666666666666667));
  out[0] = t15;
  out[1] = t90;
  out[2] = t91;
  out[3] = t93;
RM_UNROLL
  for (int d = 0; d < P; ++d) {
    const Real d231 = x[1] * Real(2.0) * dx[4 * d + 1];
    const Real d233 = x[2] * Real(2.0) * dx[4 * d + 2];
    const Real d235 = x[3] * Real(2.0) * dx[4 * d + 3];
    const Real d236 = d231 + d233 + d235;
    const Real d237 = t25 * Real(0.5) * d236;
    const Real d780 = Real(-1.0) * t25 * t89 * t96 * d236;
    const Real d240 = params[1] * dparams[NP * d + 0];
    const Real d242 = params[0] * dparams[NP * d + 1];
    const Real d243 = d240 + d242;
    const Real d245 = params[0] * params[1] * Real(-2.0) * d243;
    const Real d781 = t15 * dparams[NP * d + 0];
    const Real d782 = params[0] * t25 * Real(0.5) * d236;
    const Real d784 = d245 + d781 + d782;
    const Real d787 = t23 * Real(0.5) * d784 * t785;
    const Real d788 = d780 + d787;
    const Real d789 = t86 * dparams[NP * d + 0];
    const Real d793 = params[1] * dparams[NP * d + 1] * Real(-18.0);
    const Real d796 = Real(8.0) * dparams[NP * d + 1] * t794;
    const Real d797 = params[1] * Real(2.0) * t76 * dparams[NP * d + 1];
    const Real d800 = params[1] * t74 * dparams[NP * d + 1] * Real(-8.0);
    const Real d802 = params[1] * t72 * Real(-2.0) * dparams[NP * d + 1];
    const Real d803 = d800 + d802;
    const Real d806 = t57 * Real(0.5) * d803 * t804;
    const Real d808 = d793 + d796 + d797 + d806;
    const Real d809 = Real(0.3333333333333333) * t790 * d808;
    const Real d811 = params[1] * t76 * Real(-2.0) * dparams[NP * d + 1];
    const Real d812 = t57 * Real(-0.5) * d803 * t804;
    const Real d814 = d793 + d796 + d811 + d812;
    const Real d815 = Real(0.3333333333333333) * t810 * d814;
    const Real d816 = d809 + d815;
    const Real d817 = params[0] * d816;
    const Real d818 = d789 + d817;
    const Real d819 = Real(20.0) * dparams[NP * d + 0];
    tout[4 * d + 0] = d237;
    tout[4 * d + 1] = d788;
    tout[4 * d + 2] = d818;
    tout[4 * d + 3] = d819;
  }
}

// The functions above as one type, so generic code can take the metric as a
// template parameter (rm::trace_ray<rm::kerr::Metric>(...)).
struct Metric {
  static constexpr int PARAM_COUNT = 2;
  static constexpr bool HAS_HORIZON = true;
  static constexpr bool HAS_DISK = true;
  template <typename Real>
  RM_HD static void eval(const Real x[4], const Real* p, Real g[16], Real dg[64]) { metric_eval(x, p, g, dg); }
  template <typename Real>
  RM_HD static Real rhs(const Real y[8], const Real* p, Real dy[8]) { return reissner_nordstrom::geodesic_rhs(y, p, dy); }
  template <typename Real>
  RM_HD static Real horizon_value(const Real x[4], const Real* p) { return reissner_nordstrom::horizon_value(x, p); }
  template <typename Real>
  RM_HD static Real disk_radius(const Real x[4], const Real* p) { return reissner_nordstrom::disk_radius(x, p); }
  template <typename Real>
  RM_HD static Real disk_omega(const Real x[4], const Real* p) { return reissner_nordstrom::disk_omega(x, p); }
  template <typename Real>
  RM_HD static Real disk_inner(const Real x[4], const Real* p) { return reissner_nordstrom::disk_inner(x, p); }
  template <typename Real>
  RM_HD static Real disk_outer(const Real x[4], const Real* p) { return reissner_nordstrom::disk_outer(x, p); }
  template <typename Real>
  RM_HD static Real length_scale(const Real x[4], const Real* p) { return reissner_nordstrom::length_scale(x, p); }
  template <typename Real, int P>
  RM_HD static void jvp(const Real x[4], const Real* p, const Real* dx, const Real* dp, Real g[16], Real dg[64], Real* tg, Real* tdg) {
    reissner_nordstrom::metric_jvp<Real, P>(x, p, dx, dp, g, dg, tg, tdg);
  }
  template <typename Real, int P>
  RM_HD static void disk_jvp(const Real x[4], const Real* p, const Real* dx, const Real* dp, Real out[4], Real* tout) {
    reissner_nordstrom::disk_jvp<Real, P>(x, p, dx, dp, out, tout);
  }
};

